local records = {
    { name = "Zara", score = 90 },
    { name = "Ari", score = 90 },
    { name = "Mina", score = 95 },
}
table.sort(records, function(a, b)
    if a.score ~= b.score then return a.score > b.score end
    return a.name < b.name
end)
for _, item in ipairs(records) do print(item.name, item.score) end

